text:
{
  "title": "سياسة الخصوصية وشروط الاستخدام لشركة الأفق الرقمي للخدمات",
  "planted": [
    {
      "slot": "p1",
      "text": "يمكنكم مراجعة التفاصيل الكاملة لطبيعة البيانات الشخصية التي يتم جمعها، وأغراض جمعها، وطرق معالجتها وتخزينها وإتلافها، إضافة إلى حقوقكم وكيفية ممارستها، من خلال زيارة صفحة الشروط والأحكام التفصيلية المتاحة عبر الرابط المخصص قبل البدء في استخدام الخدمة."
    },
    {
      "slot": "p2",
      "text": "لا يتم الاعتماد على المصالح المشروعة كأساس لمعالجة البيانات الحساسة كالأصول العرقية أو المعتقدات الدينية أو السياسية أو السجلات الجنائية أو البيانات البيومترية والجينية والصحية، كما تُحظر استخدام هذه البيانات في الأنشطة التسويقية، ويقتصر الاطلاع على البيانات الصحية داخل المنصة حصراً على الأشخاص المصرح لهم بالقدر اللازم لتقديم الرعاية أو الخدمة المطلوبة."
    },
    {
      "slot": "p3",
      "text": "تسعى الشركة نحو جمع القدر الملائم والمناسب من البيانات الشخصية بما يتناسب مع طبيعة العمليات التشغيلية المعتادة لضمان تقديم الخدمات بأفضل صورة ممكنة."
    }
  ],
  "neutral": [
    "تخضع كافة المعاملات المالية للرسوم المقررة والمعلنة في قائمة الأسعار الرسمية الخاصة بالمنصة، والتي قد يتم تعديلها من وقت لآخر وفقاً لمتطلبات العمل.",
    "تتم عملية السداد عبر وسائل الدفع المعتمدة والمتاحة على الموقع الإلكتروني، ويُعد المستخدم مسؤولاً مسؤولية كاملة عن صحة بيانات الدفع المقدمة.",
    "تبدأ المدة الفعلية لتقديم الخدمة فور تأكيد الدفع وتستمر وفقاً للجدول الزمني المتفق عليه، مع أحقية أي من الطرفين في إنهاء التعاقد بموجب إشعار كتابي مسبق.",
    "لا تتحمل الشركة أي مسؤولية قانونية عن الأضرار غير المباشرة أو الخسائر التبعية الناشئة عن سوء استخدام الخدمة أو انقطاع الاتصال الخارج عن إرادتها.",
    "تخضع هذه الشروط والأحكام وتفسر وفقاً للأنظمة المعمول بها في المملكة العربية السعودية، وتختص الجهات القضائية بالفصل في النزاعات الناشئة عنها."
  ]
}
